  function createActivityEmojiIcon(iconId) {
    const wrap = document.createElement("span");
    wrap.className = "activity-emoji-icon";
    wrap.setAttribute("data-card-meta", iconId);
    wrap.setAttribute("aria-hidden", "true");

    const svg = document.createElementNS("http://www.w3.org/2000/svg", "svg");
    svg.setAttribute("class", "activity-meta-icon");
    svg.setAttribute("width", "20");
    svg.setAttribute("height", "20");
    svg.setAttribute("focusable", "false");

    const use = document.createElementNS("http://www.w3.org/2000/svg", "use");
    use.setAttribute("href", `../Assets/icons/card-meta.svg#${iconId}`);
    svg.appendChild(use);
    wrap.appendChild(svg);
    return wrap;
  }

  function decorateActivityEmojiIcons(root = document.body) {
    if (!root) return;
    const skipSelector = "script, style, textarea, option, svg, .activity-emoji-icon";
    const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT, {
      acceptNode(node) {
        if (!node.nodeValue || !activityEmojiIconMap.some(([emoji]) => node.nodeValue.includes(emoji))) {
          return NodeFilter.FILTER_REJECT;
        }
        const parent = node.parentElement;
        if (!parent || parent.closest(skipSelector)) return NodeFilter.FILTER_REJECT;
        return NodeFilter.FILTER_ACCEPT;
      }
    });

    const nodes = [];
    while (walker.nextNode()) nodes.push(walker.currentNode);

    nodes.forEach(node => {
      const text = node.nodeValue;
      const fragment = document.createDocumentFragment();
      let i = 0;
      let changed = false;

      while (i < text.length) {
        const match = activityEmojiIconMap.find(([emoji]) => text.startsWith(emoji, i));
        if (match) {
          fragment.appendChild(createActivityEmojiIcon(match[1]));
          i += match[0].length;
          changed = true;
        } else {
          const next = activityEmojiIconMap
            .map(([emoji]) => {
              const index = text.indexOf(emoji, i + 1);
              return index === -1 ? text.length : index;
            })
            .reduce((min, index) => Math.min(min, index), text.length);
          fragment.appendChild(document.createTextNode(text.slice(i, next)));
          i = next;
        }
      }

      if (changed) node.replaceWith(fragment);
    });
  }

  let activityEmojiObserverStarted = false;
  let activityEmojiDecorateQueued = false;

  function queueDecorateActivityEmojiIcons() {
    if (activityEmojiDecorateQueued) return;
    activityEmojiDecorateQueued = true;
    window.requestAnimationFrame(() => {
      activityEmojiDecorateQueued = false;
      decorateActivityEmojiIcons();
    });
  }

  function startActivityEmojiIconObserver() {
    if (activityEmojiObserverStarted || !document.body) return;
    activityEmojiObserverStarted = true;
    const observer = new MutationObserver(() => queueDecorateActivityEmojiIcons());
    observer.observe(document.body, {
      childList: true,
      characterData: true,
      subtree: true
    });
  }

  function setLanguage(language) {
  
    if (!translations[language]) language = "en";
  
    document.querySelectorAll("[data-translate]").forEach(el => {
      const key = el.dataset.translate;
      const dict = translations[language];
      if (dict && Object.prototype.hasOwnProperty.call(dict, key)) {
        el.textContent = dict[key];
      }
    });

    document.querySelectorAll("[data-translate-title]").forEach(el => {
      const key = el.dataset.translateTitle;
      const dict = translations[language];
      if (dict && Object.prototype.hasOwnProperty.call(dict, key)) {
        el.setAttribute("title", dict[key]);
      }
    });

    document.querySelectorAll("[data-translate-aria-label]").forEach(el => {
      const key = el.dataset.translateAriaLabel;
      const dict = translations[language];
      if (dict && Object.prototype.hasOwnProperty.call(dict, key)) {
        el.setAttribute("aria-label", dict[key]);
      }
    });

    document.querySelectorAll("[data-translate-alt]").forEach(el => {
      const key = el.dataset.translateAlt;
      const dict = translations[language];
      if (dict && Object.prototype.hasOwnProperty.call(dict, key)) {
        el.setAttribute("alt", dict[key]);
      }
    });

    const guidedHelpText = document.getElementById("rentGuidedHelpText");
    if (guidedHelpText) {
      const selectedType =
        document.querySelector('#rentPopupOverlay input[name="rentType"]:checked')?.value || "cart";
      const guidedKey = selectedType === "cart6" ? "rent_guided_help_text_cart6" : "rent_guided_help_text_cart";
      guidedHelpText.textContent =
        translations[language][guidedKey] || translations.en[guidedKey] || guidedHelpText.textContent;
    }

    localStorage.setItem("selectedLanguage", language);
  
    document.dispatchEvent(new CustomEvent("sacramento:setLanguage", { detail: { language } }));
  
    document.querySelectorAll(".lang-btn").forEach(btn => {
      btn.classList.toggle("active", btn.dataset.lang === language);
    });

    mountCardMetaIcons();
    decorateActivityEmojiIcons();
  }

  window.sacramentoSetLanguage = setLanguage;
  window.sacramentoMountCardMetaIcons = mountCardMetaIcons;

  function openHomeLupajackSoonPopup() {
    const overlay = document.getElementById("popupLupajackSoon");
    if (!overlay) return;
    overlay.classList.add("active");
    overlay.setAttribute("aria-hidden", "false");
  }

  function closeHomeLupajackSoonPopup() {
    const overlay = document.getElementById("popupLupajackSoon");
    if (!overlay) return;
    overlay.classList.remove("active");
    overlay.setAttribute("aria-hidden", "true");
  }

  function initHomeLupajackSoonPopup() {
    const overlay = document.getElementById("popupLupajackSoon");
    if (!overlay || overlay.dataset.homeLupajackBound === "1") return;
    overlay.dataset.homeLupajackBound = "1";

    [
      document.getElementById("homeLupajackExploreBtn"),
      document.getElementById("homeMateAsadoExploreBtn"),
      document.getElementById("homePlazaExploreBtn"),
    ]
      .filter(Boolean)
      .forEach((btn) => {
        btn.addEventListener("click", (e) => {
          e.preventDefault();
          openHomeLupajackSoonPopup();
        });
      });

    const closeX = document.getElementById("closeLupajackSoonPopup");
    if (closeX) closeX.addEventListener("click", closeHomeLupajackSoonPopup);

    const okBtn = document.getElementById("lupajackSoonPopupOk");
    if (okBtn) okBtn.addEventListener("click", closeHomeLupajackSoonPopup);

    overlay.addEventListener("click", (e) => {
      if (e.target === overlay) closeHomeLupajackSoonPopup();
    });

    document.addEventListener("keydown", (e) => {
      if (e.key === "Escape" && overlay.classList.contains("active")) closeHomeLupajackSoonPopup();
    });
  }

  function initCardExperienceDetailsToggles() {
    document.querySelectorAll(".card-info-toggle").forEach((btn) => {
      const panelId = btn.getAttribute("aria-controls");
      if (!panelId) return;
      const panel = document.getElementById(panelId);
      if (!panel) return;
      btn.addEventListener("click", () => {
        const expanded = btn.getAttribute("aria-expanded") === "true";
        if (expanded) {
          panel.setAttribute("hidden", "");
          btn.setAttribute("aria-expanded", "false");
        } else {
          panel.removeAttribute("hidden");
          btn.setAttribute("aria-expanded", "true");
          mountCardMetaIcons();
        }
      });
    });
  }

  document.addEventListener("DOMContentLoaded", () => {
  if (window.SACRAMENTO_I18N_ONLY) {
    const savedLanguage = localStorage.getItem("selectedLanguage") || "en";
    setLanguage(savedLanguage);
    return;
  }

  injectRentBadgeInActivityHero();
  initRentPopupBehavior();

    /* ===== LANGUAGE ===== */
    const savedLanguage = localStorage.getItem("selectedLanguage") || "en";
    setLanguage(savedLanguage);
    startActivityEmojiIconObserver();
  
    document.querySelectorAll(".lang-btn").forEach(button => {
      button.addEventListener("click", () => {
        setLanguage(button.dataset.lang);
      });
    });

    initCardExperienceDetailsToggles();
    initHomeLupajackSoonPopup();

    document.querySelectorAll(".card").forEach(card => {

        const imageContainer = card.querySelector(".card-image");
        const exploreSoonBtn = card.querySelector(
          "#homeLupajackExploreBtn, #homeMateAsadoExploreBtn, #homePlazaExploreBtn"
        );
        const link = Array.from(card.querySelectorAll(".card-buttons a.btn")).find((a) => {
          const h = a.getAttribute("href");
          return h && h !== "#" && h !== "";
        });
      
        if (!imageContainer) return;
      
        imageContainer.addEventListener("click", (e) => {
      
          // 👇 evita conflicto con botones del carrusel
          if (e.target.closest(".carousel-btn")) return;
          if (e.target.closest(".discount-badge")) return;
      
          if (exploreSoonBtn) {
            e.preventDefault();
            openHomeLupajackSoonPopup();
            return;
          }

          if (!link) return;
          window.open(link.href, "_blank");
        });
      
      });
  
    /* ===== LIGHTBOX PRO (imágenes + opcional video en .gallery-grid) ===== */
  
    const mediaEls = document.querySelectorAll(
      ".gallery-grid > img, .gallery-grid > .gallery-video-thumb, .gallery-grid > video"
    );
    const lightbox = document.getElementById("lightbox");
    const lightboxImg = document.getElementById("lightboxImg");
    const closeBtn = document.getElementById("closeLightbox");
    const prevBtn = document.getElementById("prevBtn");
    const nextBtn = document.getElementById("nextBtn");
  
    let currentIndex = 0;
    const mediaArray = Array.from(mediaEls);
    let lightboxVideo = null;
  
    const ensureLightboxVideo = () => {
      if (!lightbox || !lightboxImg) return null;
      if (!lightboxVideo) {
        lightboxVideo = document.createElement("video");
        lightboxVideo.className = "lightbox-inline-video";
        lightboxVideo.controls = true;
        lightboxVideo.playsInline = true;
        lightboxVideo.setAttribute("playsinline", "");
        lightboxImg.insertAdjacentElement("afterend", lightboxVideo);
      }
      return lightboxVideo;
    };
  
    const pauseLightboxVideo = () => {
      if (lightboxVideo) {
        lightboxVideo.pause();
        lightboxVideo.removeAttribute("src");
        lightboxVideo.innerHTML = "";
        lightboxVideo.style.display = "none";
      }
    };
  
    const getGalleryVideoSrc = (videoEl) => {
      const srcEl = videoEl.querySelector("source[src]");
      if (srcEl) {
        try {
          return new URL(srcEl.getAttribute("src"), window.location.href).href;
        } catch {
          return srcEl.getAttribute("src") || "";
        }
      }
      return videoEl.currentSrc || videoEl.src || "";
    };

    const videoFromGallerySlot = (slot) => {
      if (!slot) return null;
      if (slot.classList?.contains("gallery-video-thumb")) {
        return slot.querySelector("video.gallery-grid-video-el");
      }
      if (slot.tagName === "VIDEO") return slot;
      return null;
    };
  
    const showMedia = () => {
      if (!lightboxImg || !mediaArray.length) return;
      const slot = mediaArray[currentIndex];
      const gridVideo = videoFromGallerySlot(slot);
      if (gridVideo) {
        const v = ensureLightboxVideo();
        if (!v) return;
        lightboxImg.style.display = "none";
        v.style.display = "block";
        const src = getGalleryVideoSrc(gridVideo);
        v.innerHTML = "";
        const s = document.createElement("source");
        s.src = src;
        s.type = "video/mp4";
        v.appendChild(s);
        v.load();
      } else if (slot.tagName === "IMG") {
        pauseLightboxVideo();
        lightboxImg.style.display = "block";
        lightboxImg.src = slot.src;
      }
    };
  
    const closeLightbox = () => {
      pauseLightboxVideo();
      if (lightboxImg) lightboxImg.style.display = "block";
      lightbox?.classList.remove("active");
    };
  
    if (mediaArray.length && lightbox && lightboxImg) {
      mediaArray.forEach((el, index) => {
        const open = () => {
          currentIndex = index;
          showMedia();
          lightbox.classList.add("active");
        };
        el.addEventListener("click", open);
        if (el.classList?.contains("gallery-video-thumb")) {
          el.addEventListener("keydown", (e) => {
            if (e.key === "Enter" || e.key === " ") {
              e.preventDefault();
              open();
            }
          });
        }
      });
  
      function nextImage() {
        currentIndex = (currentIndex + 1) % mediaArray.length;
        showMedia();
      }
  
      function prevImage() {
        currentIndex = (currentIndex - 1 + mediaArray.length) % mediaArray.length;
        showMedia();
      }
  
      nextBtn?.addEventListener("click", (e) => {
        e.stopPropagation();
        nextImage();
      });
      prevBtn?.addEventListener("click", (e) => {
        e.stopPropagation();
        prevImage();
      });
  
      closeBtn?.addEventListener("click", () => {
        closeLightbox();
      });
  
      lightbox.addEventListener("click", (e) => {
        if (e.target === lightbox) {
          closeLightbox();
        }
      });
  
      document.addEventListener("keydown", (e) => {
        if (!lightbox.classList.contains("active")) return;
  
        if (e.key === "ArrowRight") nextImage();
        if (e.key === "ArrowLeft") prevImage();
        if (e.key === "Escape") closeLightbox();
      });
    }
  
  });
  
  
    /* ===== SMOOTH SCROLL ===== */
    const exploreBtn = document.getElementById("exploreBtn");
  
    if (exploreBtn) {
      exploreBtn.addEventListener("click", e => {
        e.preventDefault();
        const section = document.getElementById("experiences");
        section?.querySelectorAll(".card").forEach((card) => {
          card.style.removeProperty("display");
        });
        section?.scrollIntoView({
          behavior: "smooth"
        });
      });
    }
  
  
    /* ===== CARD BUTTON ACTIVE ===== */
    document.querySelectorAll(".card").forEach(card => {
      const buttons = card.querySelectorAll(".btn");
  
      buttons.forEach(btn => {
        btn.addEventListener("click", () => {
          buttons.forEach(b => b.classList.remove("clicked"));
          btn.classList.add("clicked");
        });
      });
    });
  
  
    /* ===== ACORDEÓN ===== */
    document.querySelectorAll(".acordeon").forEach(acc => {
      acc.addEventListener("click", function () {
        document.querySelectorAll(".acordeon").forEach(o => {
          if (o !== this) o.removeAttribute("open");
        });
      });
    });
  
  
    /* ===== VIDEO HOVER ===== */
    document.querySelectorAll(".card").forEach(card => {
      const video = card.querySelector(".card-video");
  
      if (!video) return;
  
      card.addEventListener("mouseenter", () => video.play());
      card.addEventListener("mouseleave", () => {
        video.pause();
        video.currentTime = 0;
      });
    });
  
  
    /* ===== HAMBURGER MENU ===== */
    const toggle = document.querySelector(".menu-toggle");
    const menu = document.querySelector(".hamburger-menu");
  
    if (toggle && menu) {
  
      toggle.addEventListener("click", (e) => {
        e.stopPropagation();
        menu.style.display =
          menu.style.display === "block" ? "none" : "block";
      });
  
      document.addEventListener("click", (e) => {
        if (!menu.contains(e.target) && !toggle.contains(e.target)) {
          menu.style.display = "none";
        }
      });
  
    }
  
  
    /* ===== FILTER CARDS (home: #experiences .card + data-category tokens) ===== */
    const filters = document.querySelectorAll(".hamburger-menu li");
    const experienceSection = document.getElementById("experiences");
    const cards = experienceSection
      ? experienceSection.querySelectorAll(".card")
      : document.querySelectorAll("#experiences .card");

    filters.forEach((filterEl) => {
      filterEl.addEventListener("click", () => {
        const menuEl = document.querySelector(".hamburger-menu");
        if (menuEl) menuEl.style.display = "none";

        if (experienceSection) {
          experienceSection.scrollIntoView({ behavior: "smooth", block: "start" });
        }

        const category = filterEl.dataset.filter;
        if (!category) return;

        cards.forEach((card) => {
          if (category === "all") {
            card.style.removeProperty("display");
            return;
          }

          const tokens = (card.dataset.category || "")
            .trim()
            .split(/\s+/)
            .filter(Boolean);

          if (tokens.includes(category)) {
            card.style.removeProperty("display");
          } else {
            card.style.display = "none";
          }
        });
      });
    });
  
  
    document.querySelectorAll(".card").forEach(card => {

        const text = card.querySelector(".card-description");
        const btn = card.querySelector(".see-more");
      
        if (!text || !btn) return;
      
        // 👇 esperar render real
        setTimeout(() => {
      
          const isClamped = text.scrollHeight > text.clientHeight + 5;
      
          if (!isClamped) {
            btn.style.display = "none";
          }
      
        }, 100);
      
        btn.addEventListener("click", () => {
      
          const expanded = text.classList.toggle("expanded");
      
          btn.textContent = expanded ? "See less" : "See more";
      
        });
      
      });

